Output: {"entities": [{"text": "Oberste Gerichtshof", "type": "organisation", "start": 9, "end": 28}, {"text": "Dr. Grohmann", "type": "person", "start": 82, "end": 94}, {"text": "Dr. Nowotny", "type": "person", "start": 129, "end": 140}, {"text": "Hon.-Prof. PD Dr. Rassi", "type": "person", "start": 142, "end": 165}, {"text": "MMag. Sloboda und Dr. Kikinger", "type": "person", "start": 167, "end": 197}, {"text": "Janina Griesmeyer", "type": "person", "start": 258, "end": 275}, {"text": "Dr. Bernhard Birek", "type": "person", "start": 293, "end": 311}, {"text": "Josepha Stra\u00dfmer", "type": "person", "start": 368, "end": 384}, {"text": "Dr. Gernot Lehner", "type": "person", "start": 402, "end": 419}, {"text": "Oberlandesgerichts Linz", "type": "organisation", "start": 582, "end": 605}, {"text": "Landesgerichts Wels", "type": "organisation", "start": 734, "end": 753}]}

